1270	    /// S114 — the rendering is generic: every registered role produces a valid subagent definition
1271	    /// pointing at ITS OWN handoff path and ITS OWN `vajra next --role` command line.
1272	    /// The substance rule, in ONE place (S122, second cold pass). The first cut hand-mirrored
1273	    /// these assertions inside the fixture, so the fixture proved only that *the copy it retyped*
1274	    /// would reject a hollow role — loosen the real test and the "fixture" stayed green. Both the
1275	    /// real per-role test and the fixture now call THIS function, so they cannot drift apart.
1276	    ///
1277	    /// Returns `Err` naming the first failure, so a fixture can assert rejection without
1278	    /// `catch_unwind`.
1279	    fn role_prompt_substance(role: &Role) -> Result<(), String> {
1280	        if role.description.trim().is_empty() {
1281	            return Err(format!("{} has an empty description", role.name));
1282	        }
1283	        let n = role.system_prompt.trim().len();
1284	        if n <= 400 {
1285	            return Err(format!(
1286	                "{} has a stub system prompt ({n} bytes) — a role prompt this short cannot carry \
1287	                 its contract",
1288	                role.name
1289	            ));
1290	        }
1291	        let def = render_subagent_definition(role);
1292	        for required in ["You are the", "Your ONE job", "Rules:"] {
1293	            if !def.contains(required) {
1294	                return Err(format!(
1295	                    "{}'s rendered definition is missing the contract phrase {required:?}",
1296	                    role.name
1297	                ));
1298	            }
1299	        }
1300	        Ok(())
1301	    }
